package com.nequard.incidents;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="incidents") public class Incident{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(nullable=false)String title;@Column(nullable=false)String status="DETECTED";String priority;String rootCause;Double confidence;UUID organizationId;Instant detectedAt=Instant.now();Instant resolvedAt;public UUID getId(){return id;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getPriority(){return priority;}public void setPriority(String v){priority=v;}public String getRootCause(){return rootCause;}public void setRootCause(String v){rootCause=v;}public Double getConfidence(){return confidence;}public void setConfidence(Double v){confidence=v;}public UUID getOrganizationId(){return organizationId;}public void setOrganizationId(UUID v){organizationId=v;}public Instant getDetectedAt(){return detectedAt;}public Instant getResolvedAt(){return resolvedAt;}public void setResolvedAt(Instant v){resolvedAt=v;}}